import React,{useCallback,useMemo,useRef,useState} from 'react';
import {createRoot} from 'react-dom/client';
import {ReactFlowProvider} from '@xyflow/react';
import '@xyflow/react/dist/style.css';
import '../../../src/styles.css';
import {DiagramCanvas} from '../../../src/ui/Canvas';
import {DiagramCloudViewer,type ViewerSelection,type ViewerSelectionIntent} from '../../../src/react';
import {documentSchema,validateDocument,type Project} from '../../../src/core/model';

// INTERNAL Canvas interaction QA, not the independent SDK consumer compiler root.
// Entirely synthetic: no observations, source access, storage, file routes or editor capability.
function fixture():Project{return validateDocument(documentSchema.parse({schemaVersion:1,id:'synthetic-label-qa',revision:0,title:'Synthetic native relation labels',rootViewId:'root',nodes:[{id:'left',label:'Synthetic left',kind:'app',basis:'planned'},{id:'right',label:'Synthetic right',kind:'app',basis:'planned'}],edges:[{id:'edge-00',source:'left',target:'right',label:'Synthetic parallel label',kind:'dependency',basis:'planned'},{id:'edge-01',source:'left',target:'right',label:'Synthetic parallel label',kind:'query',basis:'unknown'}],views:[{id:'root',title:'Synthetic parallel short-gap scope',nodeIds:['left','right'],edgeIds:['edge-00','edge-01'],positions:{left:{x:0,y:0},right:{x:300,y:0}}}]}));}
function InternalCanvasQa(){
 const [doc,setDoc]=useState(fixture),baseline=useRef(JSON.stringify(doc)),[selected,setSelected]=useState<string|null>(null),[events,setEvents]=useState<{edgeId:string;viewId:string}[]>([]),[submits,setSubmits]=useState(0),[mounted,setMounted]=useState(true),[strictEvents,setStrictEvents]=useState<ViewerSelectionIntent[]>([]),[accept,setAccept]=useState(false);
 const selection=useMemo<ViewerSelection>(()=>({projectId:doc.id,baseRevision:doc.revision,viewId:'root',nodeId:'left'}),[doc]),[controlled,setControlled]=useState<ViewerSelection|null>(null);
 const onEdge=useCallback((edgeId:string,viewId:string)=>{setEvents(old=>[...old,{edgeId,viewId}]);setSelected(edgeId);},[]),noEdit=useCallback(()=>{},[]);
 const onStrict=useCallback((intent:ViewerSelectionIntent)=>{setStrictEvents(old=>[...old,intent]);if(accept)setControlled(intent);},[accept]);
 return <main><h1>Internal Canvas label quality fixture</h1><p>Internal interaction counters only. This bundle is not the independent SDK consumer qualification. Design is synthetic; no action executes source or edits the document.</p><div className="edge-qa-controls"><button type="button" onClick={()=>{setEvents([]);setSubmits(0);setSelected(null);}}>Reset internal counters</button><button type="button" onClick={()=>setDoc(old=>structuredClone(old))}>Clone internal document</button><button type="button" onClick={()=>setMounted(old=>!old)}>{mounted?'Unmount internal canvas':'Mount internal canvas'}</button><button type="button" onClick={()=>{setDoc(old=>validateDocument({...old,revision:old.revision+1,edges:old.edges.filter(edge=>edge.id!=='edge-00'),views:old.views.map(view=>({...view,edgeIds:view.edgeIds.filter(id=>id!=='edge-00')}))}));setSelected(null);setControlled(null);}}>Remove internal edge-00</button><button type="button" onClick={()=>setAccept(old=>!old)}>{accept?'Reject internal strict intents':'Accept internal strict intents'}</button></div>
 <form aria-label="Internal label host form" onSubmit={event=>{event.preventDefault();setSubmits(old=>old+1);}}><section className="studio" aria-label="Internal non-strict Canvas"><ReactFlowProvider>{mounted&&<DiagramCanvas canvasId="internal-label-canvas" doc={doc} view={doc.views[0]} level={0} genericIcons selected={null} selectedEdge={selected} edit={false} motion={false} trace="none" highlights={[]} onSelect={()=>setSelected(null)} onEdge={onEdge} onMove={noEdit} onConnect={noEdit} onGrid={noEdit} onAdd={noEdit}/>}</ReactFlowProvider></section><button type="submit">Submit internal label form</button></form>
 <output aria-label="Internal label form submits">{submits}</output><output aria-label="Internal edge deliveries">{JSON.stringify(events)}</output><output aria-label="Internal selected edge">{selected??'none'}</output><output aria-label="Internal canonical document unchanged">{String(JSON.stringify(doc)===baseline.current)}</output><output aria-label="Internal canonical document">{JSON.stringify(doc)}</output>
 <div className="edge-qa-viewers"><DiagramCloudViewer label="Internal strict A" apiVersion={1} document={doc} allowedViewIds={['root']} selection={controlled??selection} onSelectionChange={onStrict}/><DiagramCloudViewer label="Internal strict B" apiVersion={1} document={doc} allowedViewIds={['root']} selection={selection}/></div><output aria-label="Internal strict deliveries">{JSON.stringify(strictEvents)}</output><output aria-label="Internal strict controlled selection">{JSON.stringify(controlled??selection)}</output></main>;
}
createRoot(document.getElementById('edge-qa-root')!).render(<InternalCanvasQa/>);
